/**
 * Stripe Billing adapter. One probe = a fresh billing world on its own test clock (product,
 * prices, coupons, customer, subscription), then one `create_preview` of the probed change. The
 * same code runs against Stripe test mode and against the clone: only the SDK's host changes.
 */
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import Stripe from "stripe";
import { z } from "zod";
import type { Probe, Side, TargetAdapter } from "../../harness/src/adapter.ts";
import { JsonSchema, type Json } from "../../harness/src/json.ts";
import { probes } from "./probes.ts";
import { LifeInput, runLifecycle } from "./lifecycle.ts";
import { ExploreInput, runExplore } from "./explore.ts";
import { runWalkthrough, UiInput } from "./ui.ts";
import { runWide, WideInput } from "./wide.ts";

const Coupon = z.object({
  percent_off: z.number().optional(),
  amount_off: z.number().optional(),
  duration: z.enum(["forever", "once"]),
});
const Plan = z.object({ amount: z.number(), interval: z.enum(["month", "year"]) });
const Input = z.object({
  start: z.number(),
  billing_mode: z.enum(["flexible", "classic"]),
  plan: Plan,
  quantity: z.number(),
  coupon: Coupon.nullable(),
  change: z.object({
    plan: Plan.nullable(),
    quantity: z.number().nullable(),
    offset: z.number(),
    proration_behavior: z.enum(["create_prorations", "none", "always_invoice"]).nullable(),
    discount: Coupon.nullable(),
  }),
});

// The key comes from STRIPE_SECRET_KEY, else from the file named by STRIPE_ENV, else from .env at
// the repository root (git-ignored).
function testKey(): string {
  const file = process.env.STRIPE_ENV ?? join(import.meta.dirname, "..", "..", ".env");
  const fromFile = existsSync(file)
    ? /STRIPE_SECRET_KEY=(\S+)/.exec(readFileSync(file, "utf8"))?.[1]
    : undefined;
  const key = process.env.STRIPE_SECRET_KEY ?? fromFile;
  // Invariant 4: never record outside test mode.
  if (key?.startsWith("sk_test_") !== true) {
    throw new Error("refusing: STRIPE_SECRET_KEY is missing or not a test key (see .env.example)");
  }
  return key;
}

function client(side: Side): Stripe {
  if (side.kind === "target") return new Stripe(testKey(), { maxNetworkRetries: 2 });
  const url = new URL(side.url);
  return new Stripe("sk_test_clone", {
    host: url.hostname,
    port: Number(url.port),
    protocol: "http",
  });
}

const toJson = (v: unknown): Json => JsonSchema.parse(JSON.parse(JSON.stringify(v)));

function errorJson(e: unknown): Json {
  if (e instanceof Stripe.errors.StripeError) {
    return {
      error: { type: e.type, code: e.code ?? null, param: e.param ?? null, message: e.message },
    };
  }
  throw e;
}

async function couponId(stripe: Stripe, c: z.infer<typeof Coupon>): Promise<string> {
  const created = await stripe.coupons.create({
    duration: c.duration,
    ...(c.percent_off !== undefined ? { percent_off: c.percent_off } : {}),
    ...(c.amount_off !== undefined ? { amount_off: c.amount_off, currency: "usd" } : {}),
  });
  return created.id;
}

async function run(probe: Probe, side: Side): Promise<Record<string, Json>> {
  const ui = UiInput.safeParse(probe.input);
  if (ui.success) return runWalkthrough(client(side), ui.data);
  const explore = ExploreInput.safeParse(probe.input);
  if (explore.success) return runExplore(client(side), explore.data);
  const wide = WideInput.safeParse(probe.input);
  if (wide.success) return runWide(client(side), wide.data, toJson, errorJson);
  const life = LifeInput.safeParse(probe.input);
  if (life.success) return runLifecycle(client(side), life.data);
  const p = Input.parse(probe.input);
  const stripe = client(side);
  const clock = await stripe.testHelpers.testClocks.create({ frozen_time: p.start });
  const price = async (plan: z.infer<typeof Plan>, name: string): Promise<string> => {
    const product = await stripe.products.create({ name });
    const created = await stripe.prices.create({
      product: product.id,
      currency: "usd",
      unit_amount: plan.amount,
      recurring: { interval: plan.interval },
    });
    return created.id;
  };
  const oldPrice = await price(p.plan, "Basic");
  const newPrice = p.change.plan ? await price(p.change.plan, "Pro") : null;
  const customer = await stripe.customers.create({
    test_clock: clock.id,
    payment_method: "pm_card_visa",
    invoice_settings: { default_payment_method: "pm_card_visa" },
    preferred_locales: ["en"],
  });
  const subscription = await stripe.subscriptions.create({
    customer: customer.id,
    items: [{ price: oldPrice, quantity: p.quantity }],
    billing_mode: { type: p.billing_mode },
    ...(p.coupon ? { discounts: [{ coupon: await couponId(stripe, p.coupon) }] } : {}),
  });
  const item = subscription.items.data[0];
  if (!item) throw new Error("subscription created without an item");
  const discount = p.change.discount ? await couponId(stripe, p.change.discount) : null;

  let preview: Json;
  try {
    preview = toJson(
      await stripe.invoices.createPreview({
        subscription: subscription.id,
        subscription_details: {
          items: [
            {
              id: item.id,
              ...(newPrice !== null ? { price: newPrice } : {}),
              ...(p.change.quantity !== null ? { quantity: p.change.quantity } : {}),
            },
          ],
          proration_date: p.start + p.change.offset,
          ...(p.change.proration_behavior !== null
            ? { proration_behavior: p.change.proration_behavior }
            : {}),
        },
        ...(discount !== null ? { discounts: [{ coupon: discount }] } : {}),
      }),
    );
  } catch (e) {
    preview = errorJson(e);
  }
  const first =
    typeof subscription.latest_invoice === "string" ? subscription.latest_invoice : null;
  const invoice = first !== null ? await stripe.invoices.retrieve(first) : null;
  return {
    preview,
    first_invoice: invoice
      ? {
          subtotal: invoice.subtotal,
          total: invoice.total,
          amount_due: invoice.amount_due,
          status: invoice.status,
        }
      : null,
  };
}

const recordedWith = (): Record<string, Json> => ({
  stripe_api_version: Stripe.API_VERSION,
  stripe_node: Stripe.PACKAGE_VERSION,
});

const adapter: TargetAdapter = { probes, run, cloneEntry: "clone/server.ts", recordedWith };
export default adapter;
# Gaps: stripe-billing

Owner: main session. The hand-written account of where the clone is wrong, might be wrong, or was
never compared. The generated list is `GAPS.generated.md`; scores are in `verify/` and every
claim's single look is in `measurements.md`.

## Scope

Stripe Billing in **test mode**, USD, through the public API and the hosted Customer Portal:

- **Slice 1:** the preview (`invoices.createPreview`) of a mid-cycle change on a subscription of 1
  to 3 items sharing a monthly or yearly interval: new price, new quantity or both, at any second
  of the first period, with 0 to 2 subscription coupons (percent or amount off, forever or once)
  and an optional preview coupon, in flexible or classic billing mode, under the three proration
  behaviours. The portal's plan change flow.
- **Slice 2:** cancel at period end, reactivate, cancel now, renewals and a failing card over test
  clocks; the portal's cancel and renew flow.

The one claim with a pre-registered bound is on slice 1's `WIDE_DISTRIBUTION` (`probes.ts`):
below 1 % of cases diverge, at 99 % confidence (holdout batch 2, 473 of 473). Everything else
below is counts without a claim.

**A quarter of that batch is easy.** Of its 473 cases, 74 are Stripe errors (70 of them the
`none` behaviour given a proration date) and 56 are changes that change nothing (50 with no change at all, 6 that
ask for the current quantity). On the 343 other cases, with no failure either, the bound is 0.87 % at 95 % and 1.33 % at 99 %: on substantive
changes alone the result is "below 1 % at 95 %", not at 99 %. This split was not in the plan, so it
is descriptive only; the pre-registered claim stands as stated.

## Measured divergences

None in the claim's measurement (batch 2, 473 of 473). Measured earlier and fixed through new dev
probes, never by reading a holdout the clone was later scored on:

| When                        | Where                 | Behaviour                                                       | Fixed by                        |
| --------------------------- | --------------------- | --------------------------------------------------------------- | ------------------------------- |
| Batch 1 (448 of 473)        | 8 cases               | percent coupon over several lines: rounded on the total, spread | `dev-t2-a*`, DSC-01             |
| Batch 1                     | 7 cases               | once coupon passed to the preview: listed, at 0 when immediate  | `dev-t2-b*`, DSC-05             |
| Batch 1                     | 5 cases               | credit-line discount list in immediate flexible invoices        | `dev-t2-c*`, DSC-07             |
| Batch 1                     | 2 cases               | flexible credit whose discount prorates to 0                    | `dev-t2-d*`, DSC-08             |
| Batch 1                     | 2 cases               | interval change with the proration date at the period end       | `dev-t2-e*`, INT-02             |
| Batch 1                     | 1 case                | first invoice under the minimum charge goes to the balance      | `dev-t2-f*`, INV-01             |
| Dev, after the batch 2 look | `dev-t2-f-left56..58` | minimum charge is 56 cents; the measured clone uses 59          | not fixed in the measured clone |

The analysis of batch 1 is `analysis/batch1-failures.md`. The clone measured before that analysis
(`7238f46`) also fails 22 of batch 2's 473 cases: the second builder pass is what closed the gap.

## Rules that fit the fixtures but are thin

- **DSC-07 (credit-line discounts in immediate flexible invoices).** Implemented as a decision
  table over the observed cases, not as a mechanism (`clone/NOTES.md`). It holds on batch 2; an
  input outside the distribution may fall in a cell no fixture filled.
- **PRO-04 (rounding at exactly .5)** and **MOD-01 (classic vs flexible)**: few separating cases.
- **LIF-03 and LIF-04** have no dev fixture: coded from their statements only, unverified.

## Holes found by mutation testing

`audit/mutate.ts` planted 40 one-line bugs in the clone's logic and replayed the 715 dev logic
fixtures the unchanged clone passes: 30 were caught. Of the 10 that survived, 4 change nothing by
construction (a loop's safety bound, two constants of the ID minter, whose IDs are compared
canonicalised, and distributing a zero remainder). The other 6 are behaviour no fixture pins:

- the error returned for an object that does not exist (`api.ts:44`);
- which of two events at the same instant comes first (`life.ts:206`);
- a once-only coupon over the subscription lifecycle (`life.ts:83`);
- listing invoice items when several customers exist; every probe has one (`api.ts:307`);
- the delay before the first payment retry; only the second is pinned (`life.ts:31`);
- a routing condition for invoice items (`api.ts:431`).

## Compared nowhere (outside the probe space)

Not covered by a fixture, unverified: taxes, currencies other than USD, more than three items,
mixed intervals in one subscription, metered and tiered prices, schedules, trials during a
change, `repeating` coupons, promotion codes, customer balance beyond the minimum-charge case,
3D Secure and payment failures other than `pm_card_chargeCustomerFail`, portal flows other than
plan change, quantity change and cancel/renew, the retention coupon, the cancellation reason
dialog, **live mode** (assumed equal to test mode).

## Blind spots by design

- **Lifecycle snapshots and the post-flow account state are projections** (`lifecycle.ts`,
  `ui.ts`): fields outside them are not compared. Previews are compared field by field.
- **Screens:** link targets are dropped (they carry session secrets); element boxes are compared
  within 16 px (one trial on 2026-10-01, not kept, rendered the same Stripe page up to 12 px
  apart between macOS and the Linux image; the other 4 px are margin, and a builder can tune to
  the tolerance); the thumbnail is reported, never scored; the test card's expiry text is masked
  (`policy.json`), since it depends on the recording day.
- **Time bombs.** The card expiry follows the real date; the portal prints a year on dates that
  are not in the current real year, so screens recorded in 2026 will differ from Stripe's in 2027.
  Fixtures are frozen, so the clone keeps passing: the divergence becomes invisible.
- **The hash-split holdout's inputs** are visible to the builder in `probes.ts` (outputs are not).
  Pre-registered batches have hidden seeds.

## Evaluator integrity

- **One builder run per clone version.** The claim is about this clone, not about the factory's
  ability to build such clones every time; see `variance.md` for further builds.
- **The hash-split holdout is not clean:** looked at under several clone versions, and it holds
  cases designed after earlier failures. It is reported with that status and carries no claim.
- **Both batch runs were logged `dirty: true`** because the dirty-tree check excluded nothing (a
  pathspec bug, fixed in `1c64c83`); the scored code is the stated commit (`measurements.md`).

/**
 * The widened slice-1 probe: the same mid-cycle change previewed with `create_preview`, on a
 * subscription of one to three items sharing a monthly or yearly interval, with up to two
 * coupons. The original single-item probe is the special case of one item and at most one coupon;
 * it keeps its own input shape so that its recorded fixtures stay valid.
 */
import type Stripe from "stripe";
import { z } from "zod";
import type { Json } from "../../harness/src/json.ts";

export const Coupon = z.object({
  percent_off: z.number().optional(),
  amount_off: z.number().optional(),
  duration: z.enum(["forever", "once"]),
});
export type Coupon = z.infer<typeof Coupon>;

const Interval = z.enum(["month", "year"]);

export const WideInput = z.object({
  kind: z.literal("wide"),
  start: z.number(),
  billing_mode: z.enum(["flexible", "classic"]),
  interval: Interval,
  items: z
    .array(z.object({ amount: z.number(), quantity: z.number() }))
    .min(1)
    .max(4),
  coupons: z.array(Coupon).max(2),
  change: z.object({
    item: z.number().int().min(0),
    amount: z.number().nullable(),
    // Only with a single item: a subscription's items share one interval.
    interval: Interval.nullable(),
    quantity: z.number().nullable(),
    offset: z.number(),
    proration_behavior: z.enum(["create_prorations", "none", "always_invoice"]).nullable(),
    discount: Coupon.nullable(),
  }),
});
export type WideInput = z.infer<typeof WideInput>;

export async function couponId(stripe: Stripe, c: Coupon): Promise<string> {
  const created = await stripe.coupons.create({
    duration: c.duration,
    ...(c.percent_off !== undefined ? { percent_off: c.percent_off } : {}),
    ...(c.amount_off !== undefined ? { amount_off: c.amount_off, currency: "usd" } : {}),
  });
  return created.id;
}

export async function runWide(
  stripe: Stripe,
  p: WideInput,
  toJson: (v: unknown) => Json,
  errorJson: (e: unknown) => Json,
): Promise<Record<string, Json>> {
  const clock = await stripe.testHelpers.testClocks.create({ frozen_time: p.start });
  const price = async (amount: number, interval: "month" | "year", name: string) => {
    const product = await stripe.products.create({ name });
    const created = await stripe.prices.create({
      product: product.id,
      currency: "usd",
      unit_amount: amount,
      recurring: { interval },
    });
    return created.id;
  };
  const names = ["Plan A", "Plan B", "Plan C"];
  const prices: string[] = [];
  for (const [i, item] of p.items.entries())
    prices.push(await price(item.amount, p.interval, names[i] ?? "Plan"));
  const changed = p.items[p.change.item];
  if (!changed) throw new Error(`change.item ${String(p.change.item)} is out of range`);
  const newPrice =
    p.change.amount !== null || p.change.interval !== null
      ? await price(p.change.amount ?? changed.amount, p.change.interval ?? p.interval, "Plan New")
      : null;
  const customer = await stripe.customers.create({
    test_clock: clock.id,
    payment_method: "pm_card_visa",
    invoice_settings: { default_payment_method: "pm_card_visa" },
    preferred_locales: ["en"],
  });
  const discounts: { coupon: string }[] = [];
  for (const c of p.coupons) discounts.push({ coupon: await couponId(stripe, c) });
  const subscription = await stripe.subscriptions.create({
    customer: customer.id,
    items: p.items.map((item, i) => ({ price: prices[i] ?? "", quantity: item.quantity })),
    billing_mode: { type: p.billing_mode },
    ...(discounts.length > 0 ? { discounts } : {}),
  });
  const target = subscription.items.data.find((i) => i.price.id === prices[p.change.item]);
  if (!target) throw new Error("subscription created without the changed item");
  const discount = p.change.discount ? await couponId(stripe, p.change.discount) : null;

  let preview: Json;
  try {
    preview = toJson(
      await stripe.invoices.createPreview({
        subscription: subscription.id,
        subscription_details: {
          items: [
            {
              id: target.id,
              ...(newPrice !== null ? { price: newPrice } : {}),
              ...(p.change.quantity !== null ? { quantity: p.change.quantity } : {}),
            },
          ],
          proration_date: p.start + p.change.offset,
          ...(p.change.proration_behavior !== null
            ? { proration_behavior: p.change.proration_behavior }
            : {}),
        },
        ...(discount !== null ? { discounts: [{ coupon: discount }] } : {}),
      }),
    );
  } catch (e) {
    preview = errorJson(e);
  }
  const first =
    typeof subscription.latest_invoice === "string" ? subscription.latest_invoice : null;
  const invoice = first !== null ? await stripe.invoices.retrieve(first) : null;
  return {
    preview,
    first_invoice: invoice
      ? {
          subtotal: invoice.subtotal,
          total: invoice.total,
          amount_due: invoice.amount_due,
          status: invoice.status,
        }
      : null,
  };
}
/**
 * Slice 2: the subscription lifecycle over time. A lifecycle probe is a script of actions on one
 * subscription living on a test clock (cancel at period end, reactivate, cancel now, advance the
 * clock, swap in a failing card), with a snapshot of the subscription and its latest invoice after
 * the steps that matter. Snapshots are a projection: fields outside it are not compared.
 */
import Stripe from "stripe";
import { z } from "zod";
import type { Json } from "../../harness/src/json.ts";
import { Coupon, couponId } from "./wide.ts";

export const LifeStep = z.discriminatedUnion("do", [
  z.object({ do: z.literal("cancel_at_period_end") }),
  z.object({ do: z.literal("reactivate") }),
  z.object({ do: z.literal("cancel_now"), prorate: z.boolean(), invoice_now: z.boolean() }),
  z.object({ do: z.literal("advance"), seconds: z.number() }),
  z.object({ do: z.literal("failing_card") }),
  z.object({ do: z.literal("snapshot"), as: z.string() }),
  // Reads a subscription that does not exist, to pin the error a missing object returns.
  z.object({ do: z.literal("retrieve_missing"), as: z.string() }),
]);
export type LifeStep = z.infer<typeof LifeStep>;

export const LifeInput = z.object({
  kind: z.literal("lifecycle"),
  start: z.number(),
  amount: z.number(),
  trial_days: z.number().nullable(),
  // A coupon on the subscription from its creation; absent in fixtures recorded before it existed.
  coupon: Coupon.nullable().default(null),
  steps: z.array(LifeStep),
});
export type LifeInput = z.infer<typeof LifeInput>;

export function invoiceView(inv: Stripe.Invoice | null): Json {
  if (!inv) return null;
  return {
    status: inv.status ?? null,
    billing_reason: inv.billing_reason ?? null,
    subtotal: inv.subtotal,
    total: inv.total,
    amount_due: inv.amount_due,
    amount_paid: inv.amount_paid,
    amount_remaining: inv.amount_remaining,
    attempt_count: inv.attempt_count,
    period_start: inv.period_start,
    period_end: inv.period_end,
    lines: inv.lines.data.map((l) => ({ amount: l.amount, description: l.description ?? null })),
  };
}

async function waitReady(stripe: Stripe, clock: string): Promise<void> {
  for (let i = 0; i < 60; i += 1) {
    const c = await stripe.testHelpers.testClocks.retrieve(clock);
    if (c.status === "ready") return;
    await new Promise((r) => setTimeout(r, 1000));
  }
  throw new Error(`test clock ${clock} did not become ready`);
}

export async function runLifecycle(
  stripe: Stripe,
  input: LifeInput,
): Promise<Record<string, Json>> {
  const clock = await stripe.testHelpers.testClocks.create({ frozen_time: input.start });
  const product = await stripe.products.create({ name: "Basic" });
  const price = await stripe.prices.create({
    product: product.id,
    currency: "usd",
    unit_amount: input.amount,
    recurring: { interval: "month" },
  });
  const customer = await stripe.customers.create({
    test_clock: clock.id,
    payment_method: "pm_card_visa",
    invoice_settings: { default_payment_method: "pm_card_visa" },
    preferred_locales: ["en"],
  });
  const created = await stripe.subscriptions.create({
    customer: customer.id,
    items: [{ price: price.id }],
    ...(input.trial_days !== null ? { trial_period_days: input.trial_days } : {}),
    ...(input.coupon !== null
      ? { discounts: [{ coupon: await couponId(stripe, input.coupon) }] }
      : {}),
  });
  let now = input.start;
  const out: Record<string, Json> = {};
  for (const step of input.steps) {
    if (step.do === "cancel_at_period_end" || step.do === "reactivate") {
      await stripe.subscriptions.update(created.id, {
        cancel_at_period_end: step.do === "cancel_at_period_end",
      });
    } else if (step.do === "cancel_now") {
      await stripe.subscriptions.cancel(created.id, {
        prorate: step.prorate,
        invoice_now: step.invoice_now,
      });
    } else if (step.do === "advance") {
      now += step.seconds;
      await stripe.testHelpers.testClocks.advance(clock.id, { frozen_time: now });
      await waitReady(stripe, clock.id);
    } else if (step.do === "failing_card") {
      const pm = await stripe.paymentMethods.attach("pm_card_chargeCustomerFail", {
        customer: customer.id,
      });
      await stripe.customers.update(customer.id, {
        invoice_settings: { default_payment_method: pm.id },
      });
    } else if (step.do === "retrieve_missing") {
      try {
        await stripe.subscriptions.retrieve("sub_Missing0000000000");
        out[step.as] = { error: null };
      } catch (e) {
        if (!(e instanceof Stripe.errors.StripeError)) throw e;
        out[step.as] = {
          error: { type: e.type, code: e.code ?? null, param: e.param ?? null, message: e.message },
        };
      }
    } else {
      const sub = await stripe.subscriptions.retrieve(created.id, { expand: ["latest_invoice"] });
      const item = sub.items.data[0];
      const latest = typeof sub.latest_invoice === "object" ? sub.latest_invoice : null;
      const invoices = await stripe.invoices.list({ subscription: sub.id, limit: 10 });
      out[step.as] = {
        status: sub.status,
        cancel_at_period_end: sub.cancel_at_period_end,
        cancel_at: sub.cancel_at ?? null,
        canceled_at: sub.canceled_at ?? null,
        ended_at: sub.ended_at ?? null,
        trial_end: sub.trial_end ?? null,
        period_start: item?.current_period_start ?? null,
        period_end: item?.current_period_end ?? null,
        latest_invoice: invoiceView(latest),
        invoice_count: invoices.data.length,
      };
    }
  }
  return out;
}

/**
 * The clone: the Stripe Billing API slice the adapter drives, and the Customer Portal (its pages
 * and the JSON endpoints they call). State is in memory only and reset by `POST /__reset`.
 */
import type { RunningClone } from "../../../harness/src/adapter.ts";
import {
  parseNestedForm,
  startCloneServer,
  type CloneApp,
} from "../../../harness/src/clone-kit.ts";
import { handleApi } from "./api.ts";
import { handlePortal } from "./portal.ts";
import { seed, type State } from "./state.ts";

const app: CloneApp<State> = {
  seed,
  handle: (req, state) => {
    const params = { ...parseNestedForm(req.query), ...req.body };
    const portal = handlePortal(state, req, params);
    if (portal) return portal;
    const api = handleApi(state, req, params);
    if (api) return api;
    return {
      status: 404,
      body: {
        error: {
          type: "invalid_request_error",
          message: `Unrecognized request URL (${req.method}: ${req.path}).`,
        },
      },
    };
  },
};

export function startClone(port: number): Promise<RunningClone> {
  return startCloneServer(app, port);
