/** In-memory account state of the clone. JSON-serialisable, rebuilt from scratch by `seed()`. */
import type { Interval } from "./time.ts";

export type BillingMode = "flexible" | "classic";

export interface Clock {
  id: string;
  frozen_time: number;
  created: number;
}

export interface Product {
  id: string;
  name: string;
}

export interface Price {
  id: string;
  product: string;
  unit_amount: number;
  currency: string;
  interval: Interval;
}

export interface Coupon {
  id: string;
  percent_off: number | null;
  amount_off: number | null;
  duration: "forever" | "once";
}

export interface PaymentMethod {
  id: string;
  customer: string | null;
  fails: boolean;
}

export interface Customer {
  id: string;
  clock: string | null;
  default_payment_method: string | null;
  created: number;
  // What the customer owes (positive) or is owed (negative), carried to the next invoice.
  balance: number;
}

export interface Discount {
  id: string;
  coupon: string;
  customer: string;
  subscription: string | null;
  start: number;
  // A once coupon is spent by the first invoice it discounts.
  used: boolean;
}

// What the invoice that billed the current period charged for one item.
export interface Billed {
  invoice: string;
  line: string;
  amount: number;
  discounts: { discount: string; amount: number }[];
}

export interface SubItem {
  id: string;
  price: string;
  quantity: number;
  created: number;
  billed: Billed | null;
}

export interface Subscription {
  id: string;
  customer: string;
  items: SubItem[];
  billing_mode: BillingMode;
  discounts: string[];
  anchor: number;
  period_start: number;
  period_end: number;
  status: "active" | "trialing" | "past_due" | "canceled";
  created: number;
  latest_invoice: string | null;
  cancel_at_period_end: boolean;
  cancel_at: number | null;
  canceled_at: number | null;
  ended_at: number | null;
  trial_start: number | null;
  trial_end: number | null;
}

export interface DiscountAmount {
  discount: string;
  amount: number;
}

export interface Line {
  id: string;
  amount: number;
  description: string;
  period: { start: number; end: number };
  price: string;
  quantity: number;
  proration: boolean;
  discountable: boolean;
  discount_amounts: DiscountAmount[];
  subscription_item: string | null;
  invoice_item: string | null;
  credited: { invoice: string; line: string } | null;
  unit_amount_decimal: string | null;
}

export interface Invoice {
  id: string;
  customer: string;
  subscription: string | null;
  lines: Line[];
  discounts: string[];
  total_discount_amounts: DiscountAmount[];
  billing_reason: string;
  status: "draft" | "open" | "paid";
  created: number;
  period_start: number;
  period_end: number;
  attempt_count: number;
  amount_paid: number;
  auto_advance: boolean;
  next_payment_attempt: number | null;
  proration_date: number | null;
  // Seconds of the next retry, while a failed invoice is still open.
  retries: number[];
  // The customer balance the invoice starts from (added to what is due).
  starting_balance: number;
  // An amount due below the minimum charge, moved to the customer balance instead (INV-01).
  deferred: number;
}

export interface InvoiceItem {
  id: string;
  customer: string;
  subscription: string;
  line: Line;
  invoice: string | null;
}

export interface PortalConfig {
  id: string;
  cancel_enabled: boolean;
  allowed_updates: string[];
  products: { product: string; prices: string[] }[];
}

export interface PortalSession {
  id: string;
  customer: string;
  configuration: string;
  created: number;
}

export interface State {
  n: number;
  clocks: Record<string, Clock>;
  products: Record<string, Product>;
  prices: Record<string, Price>;
  coupons: Record<string, Coupon>;
  customers: Record<string, Customer>;
  payment_methods: Record<string, PaymentMethod>;
  discounts: Record<string, Discount>;
  subscriptions: Record<string, Subscription>;
  invoices: Record<string, Invoice>;
  invoice_items: Record<string, InvoiceItem>;
  configs: Record<string, PortalConfig>;
  sessions: Record<string, PortalSession>;
}

export function seed(): State {
  return {
    n: 0,
    clocks: {},
    products: {},
    prices: {},
    coupons: {},
    customers: {},
    payment_methods: {},
    discounts: {},
    subscriptions: {},
    invoices: {},
    invoice_items: {},
    configs: {},
    sessions: {},
  };
}

const ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";

// Deterministic IDs: the same calls after a reset mint the same IDs.
export function mint(state: State, prefix: string): string {
  state.n += 1;
  const n = state.n;
  let x = n * 7919 + 104729;
  let s = "";
  while (s.length < 14) {
    s = (ALPHABET[x % 62] ?? "0") + s;
    x = Math.floor(x / 62) + n * 31;
  }
  // Stripe IDs start with an upper-case letter or digit after the prefix; keep one fixed shape.
  return `${prefix}_1${s}`;
}

export function get<T>(table: Record<string, T>, id: string): T | undefined {
  return Object.hasOwn(table, id) ? table[id] : undefined;
}

// The clock time a customer lives on (its test clock), or the subscription's creation time.
export function nowFor(state: State, customer: string): number {
  const c = get(state.customers, customer);
  const clock = c?.clock ? get(state.clocks, c.clock) : undefined;
  return clock ? clock.frozen_time : Math.floor(Date.now() / 1000);
}
/** Calendar helpers: billing periods anchored on a day of month, and the date formats Stripe prints. */

export type Interval = "month" | "year";

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const LONG_MONTHS = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];

// `anchor` plus `n` intervals: same day of month (clamped to the month's end) and time of day.
export function addIntervals(anchor: number, interval: Interval, n: number): number {
  const d = new Date(anchor * 1000);
  const months = interval === "year" ? 12 * n : n;
  const y = d.getUTCFullYear();
  const m = d.getUTCMonth() + months;
  const last = new Date(Date.UTC(y, m + 1, 0)).getUTCDate();
  const day = Math.min(d.getUTCDate(), last);
  return Date.UTC(y, m, day, d.getUTCHours(), d.getUTCMinutes(), d.getUTCSeconds()) / 1000;
}

// The period of an anchored cycle that contains `t` (start inclusive, end exclusive).
export function periodAt(anchor: number, interval: Interval, t: number): [number, number] {
  let k = 0;
  while (addIntervals(anchor, interval, k + 1) <= t) k += 1;
  return [addIntervals(anchor, interval, k), addIntervals(anchor, interval, k + 1)];
}

const pad = (n: number): string => String(n).padStart(2, "0");

// "15 Oct 2026", as in proration line descriptions.
export function shortDate(t: number): string {
  const d = new Date(t * 1000);
  return `${pad(d.getUTCDate())} ${MONTHS[d.getUTCMonth()] ?? ""} ${d.getUTCFullYear()}`;
}

// "October 21, 2026", as in the portal.
export function longDate(t: number): string {
  const d = new Date(t * 1000);
  return `${LONG_MONTHS[d.getUTCMonth()] ?? ""} ${d.getUTCDate()}, ${d.getUTCFullYear()}`;
}

// "Oct 21", as in the portal's badges.
export function monthDay(t: number): string {
  const d = new Date(t * 1000);
  return `${MONTHS[d.getUTCMonth()] ?? ""} ${d.getUTCDate()}`;
}

// "$2,500.00"
export function money(cents: number): string {
  const sign = cents < 0 ? "-" : "";
  const abs = Math.abs(cents);
  const whole = Math.floor(abs / 100)
    .toString()
    .replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  return `${sign}$${whole}.${pad(abs % 100)}`;
}
