export function couponJson(c: Coupon): Json {
  return {
    id: c.id,
    object: "coupon",
    amount_off: c.amount_off,
    currency: c.amount_off !== null ? "usd" : null,
    duration: c.duration,
    percent_off: c.percent_off,
    valid: true,
  };
}

export function priceJson(state: State, id: string): Json {
  const p = priceOf(state, id);
  return {
    id: p.id,
    object: "price",
    active: true,
    currency: p.currency,
    product: p.product,
    recurring: { interval: p.interval, interval_count: 1, usage_type: "licensed" },
    type: "recurring",
    unit_amount: p.unit_amount,
    unit_amount_decimal: String(p.unit_amount),
  };
}

export function subscriptionJson(state: State, sub: Subscription, expandInvoice: boolean): Json {
  const latest = sub.latest_invoice ? get(state.invoices, sub.latest_invoice) : undefined;
  return {
    id: sub.id,
    object: "subscription",
    billing_cycle_anchor: sub.anchor,
    billing_mode: { type: sub.billing_mode },
    cancel_at: sub.cancel_at,
    cancel_at_period_end: sub.cancel_at_period_end,
    canceled_at: sub.canceled_at,
    created: sub.created,
    currency: "usd",
    customer: sub.customer,
    discounts: [...sub.discounts],
    ended_at: sub.ended_at,
    items: {
      object: "list",
      data: sub.items.map((it) => ({
        id: it.id,
        object: "subscription_item",
        created: it.created,
        current_period_end: sub.period_end,
        current_period_start: sub.period_start,
        price: priceJson(state, it.price),
        quantity: it.quantity,
        subscription: sub.id,
      })),
      has_more: false,
      total_count: sub.items.length,
      url: `/v1/subscription_items?subscription=${sub.id}`,
    },
    latest_invoice:
      expandInvoice && latest ? invoiceJson(state, latest, false) : sub.latest_invoice,
    livemode: false,
    start_date: sub.created,
    status: sub.status,
    trial_end: sub.trial_end,
    trial_start: sub.trial_start,
  };
}

/** The public Stripe API surface the adapter drives (form-encoded v1 endpoints). */
import type { CloneRequest, CloneResponse } from "../../../harness/src/clone-kit.ts";
import type { Json } from "../../../harness/src/json.ts";
import {
  allocate,
  amountDue,
  deferSmall,
  draftFromPlan,
  isPlanError,
  planChange,
  priceOf,
  productName,
  recurringDescription,
  specsOf,
  type Behavior,
  type ItemChange,
} from "./billing.ts";
import { advanceClock, cancelNow } from "./life.ts";
import { couponJson, invoiceJson, priceJson, subscriptionJson } from "./objects.ts";
import {
  get,
  mint,
  nowFor,
  type Discount,
  type Invoice,
  type Line,
  type State,
  type Subscription,
} from "./state.ts";
import { addIntervals, type Interval } from "./time.ts";

type Params = Record<string, Json>;

export const ok = (body: Json): CloneResponse => ({ status: 200, body });
export const fail = (
  status: number,
  message: string,
  param: string | null = null,
): CloneResponse => ({
  status,
  body: { error: { type: "invalid_request_error", message, param } },
});
const missing = (what: string, id: string): CloneResponse =>
  fail(404, `No such ${what}: '${id}'`, "id");

export function str(v: Json | undefined): string | null {
  return typeof v === "string" ? v : typeof v === "number" ? String(v) : null;
}
export function num(v: Json | undefined): number | null {
  const s = str(v);
  if (s === null || s === "") return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}
export function obj(v: Json | undefined): Params {
  return v !== null && typeof v === "object" && !Array.isArray(v) ? v : {};
}
export function arr(v: Json | undefined): Json[] {
  if (Array.isArray(v)) return v;
  if (v !== null && typeof v === "object") return Object.values(v);
  return [];
}
const bool = (v: Json | undefined): boolean => v === true || v === "true";

function newDiscount(
  state: State,
  coupon: string,
  customer: string,
  sub: string | null,
  now: number,
): Discount {
  const d: Discount = {
    id: mint(state, "di"),
    coupon,
    customer,
    subscription: sub,
    start: now,
    used: false,
  };
  state.discounts[d.id] = d;
  return d;
}

// pm_card_* tokens resolve to a new payment method each time.
function paymentMethodFrom(state: State, token: string, customer: string | null): string {
  if (get(state.payment_methods, token)) return token;
  const id = mint(state, "pm");
  state.payment_methods[id] = { id, customer, fails: token.includes("Fail") };
  return id;
}

// ------------------------------------------------------------------ first invoice

export function billFirstInvoice(state: State, sub: Subscription, now: number): Invoice {
  const id = mint(state, "in");
  const trial = sub.status === "trialing";
  const specs = trial ? [] : specsOf(state, sub.discounts);
  const lines: Line[] = sub.items.map((it) => {
    const p = priceOf(state, it.price);
    return {
      id: mint(state, "il"),
      amount: trial ? 0 : p.unit_amount * it.quantity,
      description: trial
        ? `Free trial for ${it.quantity} × ${productName(state, it.price)}`
        : recurringDescription(state, it.price, it.quantity),
      period: { start: sub.period_start, end: sub.period_end },
      price: it.price,
      quantity: it.quantity,
      proration: false,
      discountable: true,
      discount_amounts: [],
      subscription_item: it.id,
      invoice_item: null,
      credited: null,
      unit_amount_decimal: String(p.unit_amount),
    };
  });
  const alloc = allocate(
    lines.map((l) => l.amount),
    specs,
  );
  lines.forEach((l, i) => {
    l.discount_amounts = specs.map((s, k) => ({ discount: s.id, amount: alloc[k]?.[i] ?? 0 }));
  });
  sub.items.forEach((it, i) => {
    const l = lines[i];
    if (l) it.billed = { invoice: id, line: l.id, amount: l.amount, discounts: l.discount_amounts };
  });
  for (const s of specs) {
    const d = get(state.discounts, s.id);
    if (d && s.once) d.used = true;
  }
  const tda = specs.map((s, k) => ({
    discount: s.id,
    amount: (alloc[k] ?? []).reduce((a, b) => a + b, 0),
  }));
  const inv: Invoice = {
    id,
    customer: sub.customer,
    subscription: sub.id,
    lines,
    discounts: specs.map((s) => s.id),
    total_discount_amounts: tda,
    billing_reason: "subscription_create",
    status: "paid",
    created: now,
    period_start: now,
    period_end: now,
    attempt_count: 0,
    amount_paid: 0,
    auto_advance: false,
    next_payment_attempt: null,
    proration_date: null,
    retries: [],
    starting_balance: 0,
    deferred: 0,
  };
  if (!deferSmall(state, inv)) {
    const due = amountDue(inv);
    inv.amount_paid = due;
    inv.attempt_count = due > 0 ? 1 : 0;
  }
  state.invoices[id] = inv;
  sub.latest_invoice = id;
  return inv;
}

// ------------------------------------------------------------------ handlers

function createSubscription(state: State, p: Params): CloneResponse {
  const customerId = str(p.customer) ?? "";
  const customer = get(state.customers, customerId);
  if (!customer) return missing("customer", customerId);
  const now = nowFor(state, customerId);
  const id = mint(state, "sub");
  const items = arr(p.items).map((raw) => {
    const it = obj(raw);
    return {
      id: mint(state, "si"),
      price: str(it.price) ?? "",
      quantity: num(it.quantity) ?? 1,
      created: now,
      billed: null,
    };
  });
  for (const it of items) if (!get(state.prices, it.price)) return missing("price", it.price);
  const first = items[0];
  const interval: Interval = first ? priceOf(state, first.price).interval : "month";
  const trialDays = num(p.trial_period_days);
  const trialEnd = trialDays !== null ? now + trialDays * 86400 : null;
  const mode = str(obj(p.billing_mode).type) === "classic" ? "classic" : "flexible";
  const sub: Subscription = {
    id,
    customer: customerId,
    items,
    billing_mode: mode,
    discounts: [],
    anchor: trialEnd ?? now,
    period_start: now,
    period_end: trialEnd ?? addIntervals(now, interval, 1),
    status: trialEnd !== null ? "trialing" : "active",
    created: now,
    latest_invoice: null,
    cancel_at_period_end: false,
    cancel_at: null,
    canceled_at: null,
    ended_at: null,
    trial_start: trialEnd !== null ? now : null,
    trial_end: trialEnd,
  };
  for (const raw of arr(p.discounts)) {
    const coupon = str(obj(raw).coupon) ?? "";
    if (!get(state.coupons, coupon)) return missing("coupon", coupon);
    sub.discounts.push(newDiscount(state, coupon, customerId, id, now).id);
  }
  state.subscriptions[id] = sub;
  billFirstInvoice(state, sub, now);
  return ok(subscriptionJson(state, sub, false));
}

function previewInvoice(state: State, p: Params): CloneResponse {
  const subId = str(p.subscription) ?? "";
  const sub = get(state.subscriptions, subId);
  if (!sub) return missing("subscription", subId);
  const details = obj(p.subscription_details);
  const changes: ItemChange[] = arr(details.items).map((raw) => {
    const it = obj(raw);
    return { id: str(it.id) ?? "", price: str(it.price), quantity: num(it.quantity) };
  });
  const now = nowFor(state, sub.customer);
  const discounts =
    p.discounts !== undefined
      ? arr(p.discounts).map(
          (raw) => newDiscount(state, str(obj(raw).coupon) ?? "", sub.customer, null, now).id,
        )
      : null;
  const behavior = str(details.proration_behavior) as Behavior | null;
  const plan = planChange(state, sub, {
    changes,
    proration_date: num(details.proration_date),
    behavior,
    discounts,
    now,
  });
  if (isPlanError(plan)) return fail(400, plan.message, plan.param);
  const draft = draftFromPlan(
    state,
    sub,
    plan,
    { line: () => mint(state, "il_tmp"), item: () => mint(state, "ii") },
    sub.billing_mode,
  );
  const inv: Invoice = {
    id: mint(state, "upcoming_in"),
    customer: sub.customer,
    subscription: sub.id,
    lines: draft.lines,
    discounts: draft.discounts,
    total_discount_amounts: draft.total_discount_amounts,
    billing_reason: "upcoming",
    status: "draft",
    created: draft.created,
    period_start: draft.period_start,
    period_end: draft.period_end,
    attempt_count: 0,
    amount_paid: 0,
    auto_advance: !draft.immediate,
    next_payment_attempt: draft.immediate ? null : draft.created + 3600,
    proration_date: plan.proration_date,
    retries: [],
    starting_balance: get(state.customers, sub.customer)?.balance ?? 0,
    deferred: 0,
  };
  return ok(invoiceJson(state, inv, true));
}

function updateSubscription(state: State, sub: Subscription, p: Params): CloneResponse {
  const now = nowFor(state, sub.customer);
  if (p.cancel_at_period_end !== undefined) {
    const on = bool(p.cancel_at_period_end);
    sub.cancel_at_period_end = on;
    sub.cancel_at = on ? sub.period_end : null;
    sub.canceled_at = on ? now : null;
  }
  return ok(subscriptionJson(state, sub, false));
}

function listInvoices(state: State, q: Params): CloneResponse {
  const sub = str(q.subscription);
  const limit = num(q.limit) ?? 10;
  const all = Object.values(state.invoices)
    .filter((i) => sub === null || i.subscription === sub)
    .reverse()
    .slice(0, limit);
  return ok({
    object: "list",
    data: all.map((i) => invoiceJson(state, i, false)),
    has_more: false,
    url: "/v1/invoices",
  });
}

function listInvoiceItems(state: State, q: Params): CloneResponse {
  const customer = str(q.customer);
  const pending = bool(q.pending);
  const items = Object.values(state.invoice_items)
    .filter((i) => customer === null || i.customer === customer)
    .filter((i) => !pending || i.invoice === null)
    .reverse();
  return ok({
    object: "list",
    data: items.map((i) => ({
      id: i.id,
      object: "invoiceitem",
      amount: i.line.amount,
      customer: i.customer,
      description: i.line.description,
      invoice: i.invoice,
      period: { start: i.line.period.start, end: i.line.period.end },
      proration: i.line.proration,
      quantity: i.line.quantity,
    })),
    has_more: false,
    url: "/v1/invoiceitems",
  });
}

export function handleApi(state: State, req: CloneRequest, p: Params): CloneResponse | null {
  const parts = req.path.split("/").filter((s) => s !== "");
  if (parts[0] !== "v1") return null;
  const [, a, b, c, d] = parts;
  const m = req.method;

  if (a === "test_helpers" && b === "test_clocks") {
    if (m === "POST" && c === undefined) {
      const id = mint(state, "clock");
      const t = num(p.frozen_time) ?? 0;
      state.clocks[id] = { id, frozen_time: t, created: t };
      return ok(clockJson(state, id));
    }
    const clock = c !== undefined ? get(state.clocks, c) : undefined;
    if (!clock || c === undefined) return missing("test_clock", c ?? "");
    if (m === "GET") return ok(clockJson(state, c));
    if (m === "POST" && d === "advance") {
      advanceClock(state, clock, num(p.frozen_time) ?? clock.frozen_time);
      return ok(clockJson(state, c));
    }
  }
  if (a === "products" && m === "POST" && b === undefined) {
    const id = mint(state, "prod");
    state.products[id] = { id, name: str(p.name) ?? "" };
    return ok({ id, object: "product", name: str(p.name) ?? "", active: true });
  }
  if (a === "prices" && m === "POST" && b === undefined) {
    const id = mint(state, "price");
    const interval = str(obj(p.recurring).interval) === "year" ? "year" : "month";
    state.prices[id] = {
      id,
      product: str(p.product) ?? "",
      unit_amount: num(p.unit_amount) ?? 0,
      currency: str(p.currency) ?? "usd",
      interval,
    };
    return ok(priceJson(state, id));
  }
  if (a === "coupons" && m === "POST" && b === undefined) {
    const id = mint(state, "coupon");
    const coupon = {
      id,
      percent_off: num(p.percent_off),
      amount_off: num(p.amount_off),
      duration: str(p.duration) === "once" ? ("once" as const) : ("forever" as const),
    };
    state.coupons[id] = coupon;
    return ok(couponJson(coupon));
  }
  if (a === "customers") {
    if (m === "POST" && b === undefined) {
      const id = mint(state, "cus");
      const clock = str(p.test_clock);
      const now = clock ? (get(state.clocks, clock)?.frozen_time ?? 0) : 0;
      const pmToken = str(p.payment_method);
      const pm = pmToken ? paymentMethodFrom(state, pmToken, id) : null;
      state.customers[id] = { id, clock, default_payment_method: pm, created: now, balance: 0 };
      return ok({
        id,
        object: "customer",
        test_clock: clock,
        invoice_settings: { default_payment_method: pm },
      });
    }
    const cus = b !== undefined ? get(state.customers, b) : undefined;
    if (!cus || b === undefined) return missing("customer", b ?? "");
    if (m === "POST" && c === undefined) {
      const dpm = str(obj(p.invoice_settings).default_payment_method);
      if (dpm) cus.default_payment_method = paymentMethodFrom(state, dpm, cus.id);
    }
    return ok({
      id: cus.id,
      object: "customer",
      test_clock: cus.clock,
      invoice_settings: { default_payment_method: cus.default_payment_method },
    });
  }
  if (a === "payment_methods" && b !== undefined && c === "attach" && m === "POST") {
    const id = paymentMethodFrom(state, b, str(p.customer));
    return ok({ id, object: "payment_method", customer: str(p.customer), type: "card" });
  }
  if (a === "subscriptions") {
    if (m === "POST" && b === undefined) return createSubscription(state, p);
    const sub = b !== undefined ? get(state.subscriptions, b) : undefined;
    if (!sub || b === undefined) return missing("subscription", b ?? "");
    if (m === "GET") {
      const expand = arr(p.expand).map(str);
      return ok(subscriptionJson(state, sub, expand.includes("latest_invoice")));
    }
    if (m === "DELETE") {
      cancelNow(state, sub, bool(p.prorate), bool(p.invoice_now));
      return ok(subscriptionJson(state, sub, false));
    }
    if (m === "POST") return updateSubscription(state, sub, p);
  }
  if (a === "invoices") {
    if (m === "POST" && b === "create_preview") return previewInvoice(state, p);
    if (m === "GET" && b === undefined) return listInvoices(state, p);
    if (m === "GET" && b !== undefined) {
      const inv = get(state.invoices, b);
      return inv ? ok(invoiceJson(state, inv, false)) : missing("invoice", b);
    }
  }
  if (a === "invoiceitems" && m === "GET" && b === undefined) return listInvoiceItems(state, p);
  return null;
}

function clockJson(state: State, id: string): Json {
  const c = get(state.clocks, id);
  return {
    id,
    object: "test_helpers.test_clock",
    created: c?.created ?? 0,
    frozen_time: c?.frozen_time ?? 0,
    livemode: false,
    status: "ready",
  };
}
/**
 * Time on a test clock: renewals at the period end, payment attempts an hour later, retries of a
 * failed payment, the end of a subscription set to cancel, and cancelling now (LIF-*).
 */
import {
  allocate,
  amountDue,
  creditLine,
  deferSmall,
  priceOf,
  recurringDescription,
  specOf,
  specsOf,
} from "./billing.ts";
import {
  get,
  mint,
  nowFor,
  type Clock,
  type Invoice,
  type Line,
  type State,
  type Subscription,
} from "./state.ts";
import { periodAt } from "./time.ts";

const HOUR = 3600;
const DAY = 86400;
// Retries after a failed renewal payment, counted from the first attempt (LIF-06: three attempts
// within five days; the spacing in between is not pinned by the recordings).
const RETRIES = [3 * DAY, 5 * DAY];

function failing(state: State, customer: string): boolean {
  const c = get(state.customers, customer);
  const pm = c?.default_payment_method
    ? get(state.payment_methods, c.default_payment_method)
    : undefined;
  return pm?.fails === true;
}

export function invoiceTotal(inv: Invoice): number {
  const sub = inv.lines.reduce((a, l) => a + l.amount, 0);
  return sub - inv.total_discount_amounts.reduce((a, d) => a + d.amount, 0);
}

// Pending invoice items (prorations) of a subscription, moved onto an invoice.
export function takePending(state: State, sub: Subscription, invoice: string): Line[] {
  const out: Line[] = [];
  for (const ii of Object.values(state.invoice_items)) {
    if (ii.subscription !== sub.id || ii.invoice !== null) continue;
    ii.invoice = invoice;
    out.push({ ...ii.line, id: mint(state, "il") });
  }
  return out;
}

function renew(state: State, sub: Subscription): void {
  const start = sub.period_end;
  const interval = priceOf(state, sub.items[0]?.price ?? "").interval;
  const end = periodAt(sub.anchor, interval, start)[1];
  const id = mint(state, "in");
  const pending = takePending(state, sub, id);
  const lines: Line[] = sub.items.map((it) => {
    const p = priceOf(state, it.price);
    return {
      id: mint(state, "il"),
      amount: p.unit_amount * it.quantity,
      description: recurringDescription(state, it.price, it.quantity),
      period: { start, end },
      price: it.price,
      quantity: it.quantity,
      proration: false,
      discountable: true,
      discount_amounts: [],
      subscription_item: it.id,
      invoice_item: null,
      credited: null,
      unit_amount_decimal: String(p.unit_amount),
    };
  });
  const active = sub.discounts.filter((d) => {
    const s = specOf(state, d);
    return s !== undefined && !(s.once && get(state.discounts, d)?.used === true);
  });
  const specs = specsOf(state, active);
  const alloc = allocate(
    lines.map((l) => l.amount),
    specs,
  );
  lines.forEach((l, i) => {
    l.discount_amounts = specs.map((s, k) => ({ discount: s.id, amount: alloc[k]?.[i] ?? 0 }));
  });
  for (const s of specs) {
    const d = get(state.discounts, s.id);
    if (d && s.once) d.used = true;
  }
  sub.items.forEach((it, i) => {
    const l = lines[i];
    if (l) it.billed = { invoice: id, line: l.id, amount: l.amount, discounts: l.discount_amounts };
  });
  const all = [...pending, ...lines];
  const inv: Invoice = {
    id,
    customer: sub.customer,
    subscription: sub.id,
    lines: all,
    discounts: specs.map((s) => s.id),
    total_discount_amounts: specs.map((s, k) => ({
      discount: s.id,
      amount: (alloc[k] ?? []).reduce((a, b) => a + b, 0),
    })),
    billing_reason: "subscription_cycle",
    status: "draft",
    created: start,
    period_start: sub.period_start,
    period_end: start,
    attempt_count: 0,
    amount_paid: 0,
    auto_advance: true,
    next_payment_attempt: start + HOUR,
    proration_date: null,
    retries: [],
    starting_balance: 0,
    deferred: 0,
  };
  // The customer balance moves onto the renewal invoice; a credit beyond its total stays.
  const cus = get(state.customers, sub.customer);
  if (cus) {
    inv.starting_balance = cus.balance;
    cus.balance = Math.min(0, invoiceTotal(inv) + cus.balance);
  }
  state.invoices[id] = inv;
  sub.latest_invoice = id;
  sub.period_start = start;
  sub.period_end = end;
  if (sub.status === "trialing") sub.status = "active";
}

function attempt(state: State, inv: Invoice, at: number): void {
  const sub = inv.subscription ? get(state.subscriptions, inv.subscription) : undefined;
  const due = amountDue(inv);
  if (due === 0 || deferSmall(state, inv)) {
    inv.status = "paid";
    inv.next_payment_attempt = null;
    return;
  }
  inv.attempt_count += 1;
  if (!failing(state, inv.customer)) {
    inv.status = "paid";
    inv.amount_paid = due;
    inv.next_payment_attempt = null;
    if (sub?.status === "past_due") sub.status = "active";
    return;
  }
  inv.status = "open";
  if (inv.attempt_count === 1) inv.retries = RETRIES.map((d) => at + d);
  const next = inv.retries.shift();
  inv.next_payment_attempt = next ?? null;
  if (sub && sub.status !== "canceled") sub.status = "past_due";
}

// Runs every event of the clock's customers up to `to`, in time order.
export function advanceClock(state: State, clock: Clock, to: number): void {
  const customers = new Set(
    Object.values(state.customers)
      .filter((c) => c.clock === clock.id)
      .map((c) => c.id),
  );
  for (let guard = 0; guard < 1000; guard += 1) {
    const events: { at: number; run: () => void }[] = [];
    const consider = (at: number, run: () => void): void => {
      if (at <= to) events.push({ at, run });
    };
    for (const sub of Object.values(state.subscriptions)) {
      if (!customers.has(sub.customer) || sub.status === "canceled") continue;
      const cancelAt = sub.cancel_at;
      if (cancelAt !== null && cancelAt <= sub.period_end) {
        consider(cancelAt, () => {
          sub.status = "canceled";
          sub.ended_at = cancelAt;
        });
        continue;
      }
      consider(sub.period_end, () => {
        if (sub.cancel_at_period_end) {
          sub.status = "canceled";
          sub.ended_at = sub.period_end;
        } else {
          renew(state, sub);
        }
      });
    }
    for (const inv of Object.values(state.invoices)) {
      if (!customers.has(inv.customer)) continue;
      if ((inv.status === "draft" && inv.auto_advance) || inv.status === "open") {
        const at = inv.next_payment_attempt;
        if (at !== null) {
          consider(at, () => {
            attempt(state, inv, at);
          });
        }
      }
    }
    // The earliest event first; ties keep discovery order (subscriptions before invoices).
    const chosen = events.reduce<{ at: number; run: () => void } | null>(
      (best, e) => (best === null || e.at < best.at ? e : best),
      null,
    );
    if (chosen === null) break;
    clock.frozen_time = Math.max(clock.frozen_time, chosen.at);
    chosen.run();
  }
  clock.frozen_time = to;
}

export function cancelNow(
  state: State,
  sub: Subscription,
  prorate: boolean,
  invoiceNow: boolean,
): void {
  const now = nowFor(state, sub.customer);
  if (prorate && now < sub.period_end) {
    const credits = sub.items.map((it) => creditLine(state, sub, it, now).line);
    if (invoiceNow) {
      const id = mint(state, "in");
      const pending = takePending(state, sub, id);
      const lines: Line[] = [
        ...pending,
        ...credits.map((l) => ({ ...l, id: mint(state, "il"), invoice_item: mint(state, "ii") })),
      ];
      state.invoices[id] = {
        id,
        customer: sub.customer,
        subscription: sub.id,
        lines,
        discounts: [],
        total_discount_amounts: [],
        billing_reason: "subscription_cycle",
        status: "draft",
        created: now,
        period_start: sub.period_start,
        period_end: now,
        attempt_count: 0,
        amount_paid: 0,
        auto_advance: false,
        next_payment_attempt: null,
        proration_date: null,
        retries: [],
        starting_balance: 0,
        deferred: 0,
      };
      sub.latest_invoice = id;
    } else {
      for (const l of credits) {
        const id = mint(state, "ii");
        state.invoice_items[id] = {
          id,
          customer: sub.customer,
          subscription: sub.id,
          line: { ...l, id: "", invoice_item: id },
          invoice: null,
        };
      }
    }
  }
  sub.status = "canceled";
  sub.ended_at = now;
  sub.canceled_at ??= now;
  sub.cancel_at_period_end = false;
  sub.cancel_at = null;
}

/**
 * The billing engine: discount allocation, proration arithmetic, and the plan of a subscription
 * change (which lines it bills, now or at the next renewal). Pure functions over the state; the
 * API layer turns their output into Stripe objects.
 */
import {
  get,
  type Billed,
  type Coupon,
  type DiscountAmount,
  type Invoice,
  type Line,
  type State,
  type SubItem,
  type Subscription,
} from "./state.ts";
import { addIntervals, money, periodAt, shortDate, type Interval } from "./time.ts";

// ---------------------------------------------------------------- rounding

// round(num / den) half away from zero, on exact integers (den > 0).
export function roundRatio(num: number, den: number): number {
  const sign = num < 0 ? -1 : 1;
  const a = Math.abs(num);
  return sign * Math.floor((2 * a + den) / (2 * den));
}

// Percent with up to four decimals, as an exact integer fraction of 1 000 000.
const PPM = 1_000_000;
const ppm = (percent: number): number => Math.round(percent * 10_000);

// ---------------------------------------------------------------- discounts

export interface DiscSpec {
  id: string;
  percent_off: number | null;
  amount_off: number | null;
  once: boolean;
}

export function specOf(state: State, discountId: string): DiscSpec | undefined {
  const d = get(state.discounts, discountId);
  const c = d ? get(state.coupons, d.coupon) : undefined;
  if (!d || !c) return undefined;
  return {
    id: d.id,
    percent_off: c.percent_off,
    amount_off: c.amount_off,
    once: c.duration === "once",
  };
}

export function specsOf(state: State, ids: string[]): DiscSpec[] {
  return ids.map((id) => specOf(state, id)).filter((s): s is DiscSpec => s !== undefined);
}

// Discounts apply one after another; each is spread over the discountable lines in proportion to
// what is left of them, with the rounding remainder on the last line. Result: [discount][line].
export function allocate(bases: number[], discounts: DiscSpec[]): number[][] {
  const left = bases.map((b) => Math.max(0, b));
  return discounts.map((d) => {
    const sum = left.reduce((a, b) => a + b, 0);
    const out = left.map(() => 0);
    if (sum <= 0) return out;
    // A percent-off takes round(pct x sum) and spreads it like an amount-off (DSC-01).
    const total =
      d.percent_off !== null
        ? roundRatio(sum * ppm(d.percent_off), PPM)
        : Math.min(d.amount_off ?? 0, sum);
    left.forEach((b, i) => {
      out[i] = Math.floor((total * b) / sum);
    });
    // The rounding remainder goes one cent per line, from the last line backwards.
    let rest = total - out.reduce((a, b) => a + b, 0);
    const open = left.map((b, i) => (b > 0 ? i : -1)).filter((i) => i >= 0);
    for (
      let k = open.length - 1;
      rest > 0 && open.length > 0;
      k = k === 0 ? open.length - 1 : k - 1
    ) {
      const i = open[k] ?? 0;
      out[i] = (out[i] ?? 0) + 1;
      rest -= 1;
    }
    left.forEach((b, i) => {
      left[i] = b - (out[i] ?? 0);
    });
    return out;
  });
}

export function couponLabel(c: Pick<Coupon, "percent_off" | "amount_off">): string {
  if (c.percent_off !== null) {
    const p = c.percent_off;
    return `${Number.isInteger(p * 10) ? p.toFixed(1) : String(p)}% off`;
  }
  return `${money(c.amount_off ?? 0)} off`;
}

function withDiscounts(specs: DiscSpec[]): string {
  if (specs.length === 0) return "";
  if (specs.length > 1) return " (with discounts)";
  const [s] = specs;
  return s ? ` (with ${couponLabel(s)})` : "";
}

// ---------------------------------------------------------------- lines

export function priceOf(state: State, id: string) {
  const p = get(state.prices, id);
  if (!p) throw new Error(`unknown price ${id}`);
  return p;
}

export function productName(state: State, priceId: string): string {
  const p = priceOf(state, priceId);
  return get(state.products, p.product)?.name ?? "";
}

export function recurringDescription(state: State, priceId: string, quantity: number): string {
  const p = priceOf(state, priceId);
  return `${quantity} × ${productName(state, priceId)} (at ${money(p.unit_amount)} / ${p.interval})`;
}

const qtyPrefix = (q: number): string => (q > 1 ? `${q} × ` : "");

export function intervalOf(state: State, sub: Subscription): Interval {
  const first = sub.items[0];
  return first ? priceOf(state, first.price).interval : "month";
}

// ---------------------------------------------------------------- change plan

export interface ItemChange {
  id: string;
  price: string | null;
  quantity: number | null;
}

export type Behavior = "create_prorations" | "none" | "always_invoice";

export interface PlannedItem {
  id: string;
  price: string;
  quantity: number;
}

export interface Plan {
  // Proration lines, without IDs.
  prorations: Omit<Line, "id" | "invoice_item">[];
  // The discounts each proration line actually carries (for its discount list).
  own: DiscSpec[][];
  // Per proration line: how many discounts a credit line carried (null for a charge).
  carried: (number | null)[];
  items: PlannedItem[];
  // Items whose price or quantity changes.
  changed: string[];
  // Discounts of the new state (a once coupon passed to the preview included).
  discounts: string[];
  // Whether the discounts were passed with the change rather than kept from the subscription.
  passed: boolean;
  immediate: boolean;
  // A classic interval change restarts the cycle at the clock time.
  reset: boolean;
  period_start: number;
  period_end: number;
  anchor: number;
  interval: Interval;
  proration_date: number;
  now: number;
}

export interface PlanError {
  message: string;
  param: string | null;
}

export interface PlanInput {
  changes: ItemChange[];
  proration_date: number | null;
  behavior: Behavior | null;
  // Discount IDs replacing the subscription's, or null to keep them.
  discounts: string[] | null;
  now: number;
}

function creditDiscounts(
  state: State,
  billed: Billed | null,
): { spec: DiscSpec; amount: number }[] {
  if (!billed) return [];
  return billed.discounts
    .filter((d) => d.amount !== 0)
    .map((d) => ({ spec: specOf(state, d.discount), amount: d.amount }))
    .filter((x): x is { spec: DiscSpec; amount: number } => x.spec !== undefined);
}

// Credit for the unused time of an item, from `prd` to the period end, carrying the discounts the
// item got on the invoice that billed the period (PRO-01, DSC-04).
export function creditLine(
  state: State,
  sub: Subscription,
  it: SubItem,
  prd: number,
): { line: Omit<Line, "id" | "invoice_item">; own: DiscSpec[]; carried: number } {
  const oldPrice = priceOf(state, it.price);
  const P = sub.period_end - sub.period_start;
  const r = sub.period_end - prd;
  const b = oldPrice.unit_amount * it.quantity;
  const carried = creditDiscounts(state, it.billed);
  let credit: number;
  // Flexible: a carried discount whose prorated amount rounds to 0 is not applied (DSC-08);
  // classic prorates the net amount in one step and keeps every label.
  let applied = carried.map((c) => c.spec);
  if (sub.billing_mode === "classic") {
    // Classic: the coupons apply to the credited item on its own (an amount-off coupon in full,
    // not its share of a multi-item invoice), then the net amount is prorated.
    const D = allocate(
      [b],
      carried.map((c) => c.spec),
    ).reduce((a, x) => a + (x[0] ?? 0), 0);
    credit = -roundRatio((b - D) * r, P);
  } else {
    const prorated = carried.map((c) => roundRatio(c.amount * r, P));
    credit = -(roundRatio(b * r, P) - prorated.reduce((a, x) => a + x, 0));
    applied = carried.filter((_, k) => (prorated[k] ?? 0) !== 0).map((c) => c.spec);
  }
  return {
    line: {
      amount: credit,
      description: `Unused time on ${qtyPrefix(it.quantity)}${productName(state, it.price)}${withDiscounts(applied)} after ${shortDate(prd)}`,
      period: { start: prd, end: sub.period_end },
      price: it.price,
      quantity: it.quantity,
      proration: true,
      discountable: false,
      discount_amounts: [],
      subscription_item: it.id,
      credited: it.billed ? { invoice: it.billed.invoice, line: it.billed.line } : null,
      unit_amount_decimal: null,
    },
    own: applied,
    // Discounts on the billed line, those it got nothing from included (DSC-07).
    carried: it.billed?.discounts.length ?? 0,
  };
}

export function planChange(state: State, sub: Subscription, input: PlanInput): Plan | PlanError {
  const behavior = input.behavior ?? "create_prorations";
  if (behavior === "none" && input.proration_date !== null) {
    return {
      message: "Cannot specify proration date if no proration is being done",
      param: "proration_date",
    };
  }
  const prd = input.proration_date ?? input.now;
  if (prd < sub.period_start || prd > sub.period_end) {
    return {
      message: `Cannot specify proration date outside of current subscription period or current phase. The value should be between ${sub.period_start} and ${sub.period_end}.`,
      param: "proration_date",
    };
  }
  const oldInterval = intervalOf(state, sub);
  const items: PlannedItem[] = sub.items.map((it) => {
    const ch = input.changes.find((c) => c.id === it.id);
    if (!ch) return { id: it.id, price: it.price, quantity: it.quantity };
    const priceChanged = ch.price !== null && ch.price !== it.price;
    return {
      id: it.id,
      price: ch.price ?? it.price,
      quantity: ch.quantity ?? (priceChanged ? 1 : it.quantity),
    };
  });
  const firstPlanned = items[0];
  const newInterval = firstPlanned ? priceOf(state, firstPlanned.price).interval : oldInterval;
  const discounts =
    input.discounts ?? sub.discounts.filter((id) => get(state.discounts, id)?.used !== true);
  const chargeSpecs = specsOf(state, discounts);

  let periodStart = sub.period_start;
  let periodEnd = sub.period_end;
  let anchor = sub.anchor;
  let reset = false;
  const intervalChange = newInterval !== oldInterval;
  if (intervalChange) {
    if (sub.billing_mode === "classic") {
      reset = true;
      periodStart = input.now;
      anchor = input.now;
      periodEnd = addIntervals(input.now, newInterval, 1);
    } else {
      periodEnd = addIntervals(sub.period_start, newInterval, 1);
      if (periodEnd < sub.period_end && prd >= periodEnd) {
        return {
          message: `You cannot specify \`proration_date\` past the updated subscription period end when using flexible billing mode. The value should be less than ${periodEnd}.`,
          param: null,
        };
      }
    }
  }

  const prorations: Plan["prorations"] = [];
  const own: DiscSpec[][] = [];
  const carried: (number | null)[] = [];
  const changed = sub.items
    .filter((it, i) => {
      const next = items[i];
      return next !== undefined && (next.price !== it.price || next.quantity !== it.quantity);
    })
    .map((it) => it.id);
  if (behavior !== "none") {
    sub.items.forEach((it: SubItem, i) => {
      const next = items[i];
      if (!next || !changed.includes(it.id)) return;
      // A credit with no remaining time is omitted (INT-02).
      if (prd < sub.period_end) {
        const credit = creditLine(state, sub, it, prd);
        prorations.push(credit.line);
        own.push(credit.own);
        carried.push(credit.carried);
      }
      if (reset) return;
      // Charge for the remaining time on the new item, over the new period.
      const newPrice = priceOf(state, next.price);
      const n = newPrice.unit_amount * next.quantity;
      const P2 = periodEnd - periodStart;
      const r2 = periodEnd - prd;
      const e2 = prd - periodStart;
      if (r2 <= 0) return;
      const D2 = allocate([n], chargeSpecs).map((x) => x[0] ?? 0);
      const base =
        sub.billing_mode === "classic" ? roundRatio(n * r2, P2) : Math.round(n * (1 - e2 / P2));
      // Flexible discounts the full-period amount, then prorates the discount (DSC-02); classic
      // prorates first and takes a percent-off on the prorated amount (DSC-04).
      let left = base;
      const prorated = chargeSpecs.map((s, k) => {
        const d =
          sub.billing_mode === "classic" && s.percent_off !== null
            ? roundRatio(Math.max(0, left) * ppm(s.percent_off), PPM)
            : roundRatio((D2[k] ?? 0) * r2, P2);
        left -= d;
        return d;
      });
      const applied = chargeSpecs.filter((_, k) => (prorated[k] ?? 0) !== 0);
      const charge = left;
      prorations.push({
        amount: charge,
        description: `Remaining time on ${qtyPrefix(next.quantity)}${productName(state, next.price)}${withDiscounts(applied)} after ${shortDate(prd)}`,
        period: { start: prd, end: periodEnd },
        price: next.price,
        quantity: next.quantity,
        proration: true,
        discountable: false,
        discount_amounts: [],
        subscription_item: it.id,
        credited: null,
        unit_amount_decimal: null,
      });
      own.push(applied);
      carried.push(null);
    });
  }
  const immediate = reset || (behavior === "always_invoice" && prorations.length > 0);
  return {
    prorations,
    own,
    carried,
    items,
    changed,
    discounts,
    passed: input.discounts !== null,
    immediate,
    reset,
    period_start: periodStart,
    period_end: periodEnd,
    anchor,
    interval: newInterval,
    proration_date: prd,
    now: input.now,
  };
}

export function isPlanError(p: Plan | PlanError): p is PlanError {
  return "message" in p;
}

// ---------------------------------------------------------------- invoice assembly

export interface Draft {
  lines: Line[];
  discounts: string[];
  total_discount_amounts: DiscountAmount[];
  created: number;
  period_start: number;
  period_end: number;
  immediate: boolean;
}

// The invoice a plan produces: now (immediate) or at the next renewal (prorations plus the next
// full period of every item).
export function draftFromPlan(
  state: State,
  sub: Subscription,
  plan: Plan,
  ids: { line: () => string; item: () => string },
  mode: Subscription["billing_mode"],
): Draft {
  // A once coupon passed with the change (DSC-05) is on the invoice when the change prorates
  // nothing (it then discounts the renewal) or when the invoice is immediate; with prorations
  // at the next renewal it discounts only the remaining-time charge. A once coupon kept from the
  // subscription never discounts a later invoice.
  const passedOnceShows = plan.immediate || plan.prorations.length === 0;
  const top = plan.discounts.filter((id) => {
    const s = specOf(state, id);
    if (!s) return false;
    return !s.once || (plan.passed && passedOnceShows);
  });
  const topSpecs = specsOf(state, top);
  const lines: Line[] = plan.prorations.map((p) => ({
    ...p,
    id: ids.line(),
    invoice_item: ids.item(),
  }));
  const recurring: Line[] = [];
  if (plan.reset) {
    for (const it of plan.items) {
      if (!plan.changed.includes(it.id)) continue;
      recurring.push(recurringLine(state, it, plan.period_start, plan.period_end, ids.line()));
    }
  } else if (!plan.immediate) {
    const next = periodAt(plan.anchor, plan.interval, plan.period_end)[1];
    for (const it of plan.items) {
      recurring.push(recurringLine(state, it, plan.period_end, next, ids.line()));
    }
  }
  const alloc = allocate(
    recurring.map((l) => l.amount),
    topSpecs,
  );
  recurring.forEach((l, i) => {
    l.discount_amounts = topSpecs.map((s, k) => ({ discount: s.id, amount: alloc[k]?.[i] ?? 0 }));
  });
  lines.forEach((l, i) => {
    const mine = (plan.own[i] ?? []).map((s) => s.id);
    const carried = plan.carried[i] ?? null;
    // Observed only (no documented rule): which discounts a proration line lists, at 0.
    let list: string[];
    if (mode === "classic") list = top;
    else if (plan.immediate) {
      if (carried === null) list = mine;
      // DSC-07, as the dev cases pin it: see NOTES.md, pass 4.
      else if (top.length === 0) list = [];
      else if (carried === 0) list = top;
      else if (mine.length === 0) list = [];
      else if (carried === 1) list = mine;
      else list = top;
    } else if (top.length > 0) list = top.slice(0, 1);
    else list = mine;
    l.discount_amounts = list.map((discount) => ({ discount, amount: 0 }));
  });
  const all = [...lines, ...recurring];
  const tda = top.map((discount) => ({
    discount,
    amount: all.reduce(
      (a, l) =>
        a +
        l.discount_amounts.filter((d) => d.discount === discount).reduce((x, d) => x + d.amount, 0),
      0,
    ),
  }));
  const immediate = plan.immediate;
  return {
    lines: all,
    discounts: top,
    total_discount_amounts: tda,
    created: immediate ? plan.now : plan.period_end,
    period_start: immediate ? plan.now : sub.period_start,
    period_end: immediate ? plan.now : plan.period_end,
    immediate,
  };
}

export function recurringLine(
  state: State,
  it: PlannedItem,
  start: number,
  end: number,
  id: string,
): Line {
  const p = priceOf(state, it.price);
  return {
    id,
    amount: p.unit_amount * it.quantity,
    description: recurringDescription(state, it.price, it.quantity),
    period: { start, end },
    price: it.price,
    quantity: it.quantity,
    proration: false,
    discountable: true,
    discount_amounts: [],
    subscription_item: it.id,
    invoice_item: null,
    credited: null,
    unit_amount_decimal: String(p.unit_amount),
  };
}

// The smallest amount the account charges (INV-01). The dev cases pin it above 51 cents and at
// most 291; 59 cents is 0.50 EUR (the French account's minimum) converted, an assumption.
export const MIN_CHARGE = 59;

// What an invoice asks for: its total plus the starting balance, less an amount deferred to the
// customer balance because it was below the minimum charge.
export function amountDue(inv: {
  lines: Line[];
  total_discount_amounts: DiscountAmount[];
  starting_balance: number;
  deferred: number;
}): number {
  const { total } = totals(inv.lines, inv.total_discount_amounts);
  return Math.max(0, total + inv.starting_balance) - inv.deferred;
}

// Charges below the minimum are not attempted: the amount goes to the customer balance.
export function deferSmall(state: State, inv: Invoice): boolean {
  const due = amountDue(inv);
  if (due <= 0 || due >= MIN_CHARGE) return false;
  inv.deferred += due;
  const c = get(state.customers, inv.customer);
  if (c) c.balance += due;
  inv.status = "paid";
  inv.next_payment_attempt = null;
  return true;
}

export function totals(lines: Line[], tda: DiscountAmount[]) {
  const subtotal = lines.reduce((a, l) => a + l.amount, 0);
  const discount = tda.reduce((a, d) => a + d.amount, 0);
  return { subtotal, total: subtotal - discount };
}

