// Offline analysis of renewal-line discount allocation in dev cases.
import { readdirSync, readFileSync } from "node:fs";
const D = "/work/targets/stripe-billing/fixtures/dev/";
for (const f of readdirSync(D)) {
  const j = JSON.parse(readFileSync(D + f, "utf8"));
  const pv = j.observed?.preview;
  if (!pv?.lines) continue;
  const lines = pv.lines.data.filter((l) => !l.parent.subscription_item_details.proration);
  if (lines.length < 2) continue;
  const ids = pv.discounts ?? [];
  let left = lines.map((l) => l.amount);
  for (const id of ids) {
    const obs = lines.map((l) => l.discount_amounts.find((d) => d.discount === id)?.amount ?? 0);
    const T = obs.reduce((a, b) => a + b, 0);
    const S = left.reduce((a, b) => a + b, 0);
    if (S <= 0 || T === 0) { left = left.map((b, i) => b - obs[i]); continue; }
    const fl = left.map((b) => Math.floor((T * b) / S));
    const rem = T - fl.reduce((a, b) => a + b, 0);
    const plus = obs.map((o, i) => o - fl[i]);
    if (rem > 0) {
      const fr = left.map((b) => ((T * b) / S - Math.floor((T * b) / S)).toFixed(3));
      console.log(f, "ch", j.input.change?.item, "rem", rem, "plus", plus.join(","), "frac", fr.join(","), "amts", left.join(","));
    }
    left = left.map((b, i) => b - obs[i]);
  }
}

